(()=>{'use strict';const URL='search-index-lite.json?v=20260729-grouped-v2';const TEAM_URL='ffws-br-2026-s2/teams.json?v=20260729-grouped-v2';let items=[],promise=null;const cache=new Map;const timers={};const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));function prepare(raw){return(raw||[]).map(x=>({...x,_search:norm([x.title,x.sub,...(x.aliases||[])].join(' ')),_title:norm(x.title)}))}function load(){if(items.length)return Promise.resolve(items);if(promise)return promise;promise=fetch(URL,{cache:'default'}).then(r=>{if(!r.ok)throw new Error('Busca indisponível');return r.json()}).then(d=>items=prepare(d.items||[])).catch(()=>items=[]);return promise}function newsItems(){const list=window.CFF_NOTICIAS_CACHE||window.cffNoticias||window.__CFF_NOTICIAS||[];return list.slice(0,80).map((n,i)=>({type:'news',id:n.urlInterna||n.link_original||n.id||String(i),title:n.titulo||'Notícia',sub:n.data?`Notícia • ${n.data}`:'Notícia',image:n.imagem||'central free fire.webp',url:n.urlInterna||n.link_original||'#',_search:norm([n.titulo,n.resumo,n.autor].join(' ')),_title:norm(n.titulo)}))}function score(x,q,tokens){if(x._title===q)return 1000;if(x._title.startsWith(q))return 850;if(x._search.startsWith(q))return 760;if(x._search.includes(q))return 620;let hit=0;for(const t of tokens)if(x._search.includes(t))hit++;return hit===tokens.length?420+hit*10:-1}function find(q){q=norm(q);if(q.length<2)return[];if(cache.has(q))return cache.get(q);const tokens=q.split(' ').filter(Boolean);const all=items.concat(newsItems());const out=all.map(x=>({x,s:score(x,q,tokens)})).filter(v=>v.s>=0).sort((a,b)=>b.s-a.s||a.x.title.localeCompare(b.x.title,'pt-BR')).slice(0,20).map(v=>v.x);cache.set(q,out);return out}function action(item){if(item.type==='player')location.href=`jogador.html?id=${encodeURIComponent(item.id)}`;else if(item.type==='team')location.href=`equipe.html?time=${encodeURIComponent(item.title)}`;else if(item.type==='news')location.href=item.url||'#';else window.navigate?.(item.id)}function row(x){return`<button type="button" class="search-item cff-fast-search-item" data-fast-type="${esc(x.type)}" data-fast-id="${esc(x.id)}"><img src="${esc(x.image||'silhueta.webp')}" onerror="this.onerror=null;this.src='${x.type==='team'?'escudo.webp':'silhueta.webp'}'" alt=""><span class="cff-fast-search-copy"><strong>${esc(x.title)}</strong><small>${esc(x.sub||'')}</small></span></button>`}function render(source){const input=document.getElementById(source==='desktop'?'global-search-desktop':source==='mobile'?'global-search-mobile':'global-search-page-input');const box=document.getElementById(source==='desktop'?'search-results-desktop':source==='mobile'?'search-results-mobile':'global-search-results-container');if(!input||!box)return;const q=input.value.trim();if(q.length<2){if(source==='page')box.innerHTML='<div class="global-search-empty">Digite pelo menos 2 caracteres para pesquisar.</div>';else box.style.display='none';return}const results=find(q);if(source==='page'){box.innerHTML=results.length?`<div class="global-search-summary">${results.length} resultado(s)</div><div class="global-search-grid">${results.map(row).join('')}</div>`:'<div class="global-search-empty">Nenhum resultado encontrado.</div>'}else{box.innerHTML=results.slice(0,8).map(row).join('')||'<div style="padding:15px;color:#888;text-align:center">Nenhum resultado encontrado.</div>';box.style.display='block'}}function from(source){clearTimeout(timers[source]);timers[source]=setTimeout(()=>load().then(()=>render(source)),45)}function bind(){[['global-search-desktop','desktop'],['global-search-mobile','mobile'],['global-search-page-input','page']].forEach(([id,source])=>{const input=document.getElementById(id);if(!input||input.dataset.fastBound)return;input.dataset.fastBound='1';input.removeAttribute('oninput');input.addEventListener('input',()=>from(source));input.addEventListener('focus',load,{once:true})});['search-results-desktop','search-results-mobile','global-search-results-container'].forEach(id=>{const box=document.getElementById(id);if(!box||box.dataset.fastBound)return;box.dataset.fastBound='1';box.addEventListener('click',e=>{const btn=e.target.closest('[data-fast-id]');if(!btn)return;const item=items.concat(newsItems()).find(x=>x.type===btn.dataset.fastType&&String(x.id)===btn.dataset.fastId);if(item)action(item)})});document.addEventListener('click',e=>{if(!e.target.closest('.search-container,.nav-search-wrapper,#mobile-search-bar,.global-search-page')){document.getElementById('search-results-desktop')?.style.setProperty('display','none');document.getElementById('search-results-mobile')?.style.setProperty('display','none')}})}function teamNav(){fetch(TEAM_URL,{cache:'default'}).then(r=>r.ok?r.json():{teams:[]}).then(d=>{const root=document.getElementById('nav-desktop-teams');if(!root)return;const teams=(d.teams||[]).map(t=>({title:t.name,image:t.logo||'escudo.webp'}));root.innerHTML=teams.map(t=>`<button class="nav-team-logo-btn" type="button" title="${esc(t.title)}" data-fast-team="${esc(t.title)}"><img src="${esc(t.image)}" onerror="this.onerror=null;this.src='escudo.webp'" alt="${esc(t.title)}"></button>`).join('');root.addEventListener('click',e=>{const b=e.target.closest('[data-fast-team]');if(b)location.href=`equipe.html?time=${encodeURIComponent(b.dataset.fastTeam)}`})}).catch(()=>{})}window.cffFastSearchFrom=from;window.handleGlobalSearchFrom=from;window.cffRestoreFastSearch=function(){window.handleGlobalSearchFrom=from;window.cffFastSearchFrom=from;bind()};window.openCurrentSeasonPlayer=(name,team='')=>location.href=`jogador.html?jogador=${encodeURIComponent(name)}&time=${encodeURIComponent(team)}`;window.openCurrentSeasonTeam=name=>location.href=`equipe.html?time=${encodeURIComponent(name)}`;function idlePreload(){const run=()=>load();if('requestIdleCallback'in window)requestIdleCallback(run,{timeout:3500});else setTimeout(run,2200)}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',()=>{bind();teamNav();idlePreload()},{once:true}):(bind(),teamNav(),idlePreload())})();
